// Declarations and pure functions only: see the barrel's `sideEffects` note.

/**
 * `s` without any run of `/` at its end ("https://x.test///" -> "https://x.test").
 *
 * This replaces `s.replace(/\/+$/, "")`, which backtracks quadratically: on a string with a long run
 * of slashes that is NOT at the end ("/a" + 16,000 slashes + "b/") the engine retries the run from
 * every start position and fails each time (CodeQL js/polynomial-redos). One scan from the end is
 * linear whatever the input looks like, which matters here because some callers hold a request
 * pathname.
 */
export function trimTrailingSlashes(s: string): string {
  let end = s.length;
  while (end > 0 && s.charCodeAt(end - 1) === 47) end -= 1;
  return end === s.length ? s : s.slice(0, end);
}
