// The three wire-level constants a CLIENT of the `/v1` API needs, in a module that imports nothing.
//
// WHY THIS FILE EXISTS. These values used to live next to the OpenAPI builder (`openapi.ts`) and the
// route table (`routes.ts`), both of which import zod and every contract schema. A client that
// wanted just the header name therefore dragged the whole contract layer into its bundle:
// measured on the browser extension, `background.js` was 112 119 bytes and the popup chunk
// 108 103, of which ~78 KB was zod's runtime and the route table, for three string literals.
// Pointing the SDK client and the extension at this entry took them to ~34 KB and ~30 KB.
//
// ONE SOURCE OF TRUTH: `openapi.ts` and `routes.ts` re-export these rather than declaring their
// own, so the barrel (`@marka/shared`) still exposes the same names and the OpenAPI document, the
// SDK and the extension can never disagree about them.
//
// SANCTIONED ENTRY, NOT A DEEP IMPORT: consumers write `from "@marka/shared/wire-lite"`, the
// `exports` subpath declared in this package's package.json. Keep this module free of imports; the
// moment it needs zod it has stopped being the narrow entry and belongs in the barrel.

/** The API's origin. Paths hang off `OPENAPI_SERVER_URL + V1_PATH_PREFIX`, not off this alone. */
export const OPENAPI_SERVER_URL = "https://joinmarka.com";

/** The header an API key travels in. */
export const OPENAPI_API_KEY_HEADER = "x-api-key";

/**
 * Where the `/v1` paths are actually mounted.
 *
 * The route table's paths are `/v1/…` because that is the API's own namespace, but the handlers
 * are Next App Router files under `apps/web/app/api/v1/**`, so the URL a client dials is
 * `/api/v1/…`. This constant is the ONE place that offset lives: the OpenAPI document composes it
 * into `servers[0].url` and the SDK composes it onto its base URL, so neither can drift into
 * publishing a URL that 404s.
 */
export const V1_PATH_PREFIX = "/api";

// The trailing-slash trim the SDK client needs, from a module that imports nothing. Linear, unlike
// the `/\/+$/` regex it replaces (see trailing-slashes.ts).
export { trimTrailingSlashes } from "./trailing-slashes";
