import {
  type V1CreateListingRequest,
  type V1Error,
  type V1HttpMethod,
  type V1ListCategoriesQuery,
  type V1ListCategoriesResponse,
  type V1ListListingsQuery,
  type V1ListListingsResponse,
  type V1ListOrdersQuery,
  type V1ListOrdersResponse,
  type V1ListingResponse,
  type V1MeResponse,
  type V1OrderResponse,
  type V1SearchQuery,
  type V1SearchResponse,
  type V1UpdateListingRequest,
} from "@marka/shared";
// The value imports come from the zod-free subpath, NOT the barrel: the barrel's OpenAPI builder
// and route table drag zod's runtime into every bundle that imports this client (the extension's
// MV3 worker went 34 KB -> 112 KB). Types stay on the barrel, where `import type` erases them.
import {
  OPENAPI_API_KEY_HEADER,
  OPENAPI_SERVER_URL,
  V1_PATH_PREFIX,
  trimTrailingSlashes,
} from "@marka/shared/wire-lite";
import { MarkaApiError, MarkaNetworkError } from "./errors";

/**
 * A typed client for the public `/api/v1` surface — one method per row of `V1_ROUTES`, with the
 * request and response types taken straight from the contract in @marka/shared so the SDK cannot
 * describe an endpoint the API does not have.
 *
 * The client is deliberately THIN. It does not re-validate responses: the contract schemas are
 * the compile-time types here, and a second runtime parse would double the bundle for a check the
 * server already ran. What it does own is the three things every call needs done identically —
 * the URL (origin + `V1_PATH_PREFIX` + the contract path, so the mount point is never re-encoded
 * here), the `x-api-key` header, and turning a failed answer into a thrown `MarkaApiError`.
 *
 * Configuration is constructor arguments only; nothing here reads `process.env`, so the same
 * instance is safe in a browser, a worker, or a server process, and tests inject `fetch`.
 */

/** Query values as they leave the client, before being stringified into the query string. */
type QueryParams = Readonly<Record<string, string | number | boolean | undefined>>;

export interface MarkaClientOptions {
  /** An API key created in Marka account settings (`mk_…`). Sent on every request. */
  readonly apiKey: string;
  /**
   * API **origin** — scheme and host only, e.g. `http://localhost:3001`. The `/api` mount point
   * (`V1_PATH_PREFIX`) and the `/v1/…` contract path are appended by the client, so do NOT include
   * either here. Defaults to production; point it at a local web app to develop against it.
   */
  readonly baseUrl?: string | undefined;
  /** Injectable transport. Defaults to the runtime's global `fetch`. */
  readonly fetch?: typeof globalThis.fetch | undefined;
}

/** `?a=1&b=2`, or `""` when every parameter was omitted. Undefined values are dropped entirely. */
function buildQueryString(query: QueryParams | undefined): string {
  if (!query) return "";
  const params = new URLSearchParams();
  for (const [name, value] of Object.entries(query)) {
    if (value === undefined) continue;
    params.set(name, String(value));
  }
  const serialized = params.toString();
  return serialized === "" ? "" : `?${serialized}`;
}

/** True for the `{ error, code? }` envelope every non-2xx `/v1` response carries. */
function isErrorEnvelope(payload: unknown): payload is V1Error {
  if (typeof payload !== "object" || payload === null) return false;
  const candidate: Partial<Record<keyof V1Error, unknown>> = payload;
  if (typeof candidate.error !== "string") return false;
  return candidate.code === undefined || typeof candidate.code === "string";
}

export class MarkaClient {
  readonly #apiKey: string;
  readonly #baseUrl: string;
  readonly #fetch: typeof globalThis.fetch;

  constructor(options: MarkaClientOptions) {
    this.#apiKey = options.apiKey;
    // A trailing slash would produce `//api/v1/…`, which some proxies redirect and others 404.
    this.#baseUrl = trimTrailingSlashes(options.baseUrl ?? OPENAPI_SERVER_URL);
    const injected = options.fetch;
    // Wrapped rather than stored bare so the global stays bound to its own receiver.
    this.#fetch = injected ?? ((input, init) => globalThis.fetch(input, init));
  }

  /** Get the authenticated account and its plan. */
  getMe(): Promise<V1MeResponse> {
    return this.#request("get", "/v1/me", {});
  }

  /** List your listings, newest first. */
  listListings(query?: V1ListListingsQuery): Promise<V1ListListingsResponse> {
    return this.#request("get", "/v1/listings", { query });
  }

  /** Create a draft listing. Requires the `api_write` entitlement on a key-authenticated call. */
  createListing(body: V1CreateListingRequest): Promise<V1ListingResponse> {
    return this.#request("post", "/v1/listings", { body });
  }

  /** Get one of your listings by id. */
  getListing(id: string): Promise<V1ListingResponse> {
    return this.#request("get", `/v1/listings/${encodeURIComponent(id)}`, {});
  }

  /** Update listing fields. Lifecycle transitions go through {@link publishListing}. */
  updateListing(id: string, body: V1UpdateListingRequest): Promise<V1ListingResponse> {
    return this.#request("patch", `/v1/listings/${encodeURIComponent(id)}`, { body });
  }

  /** Publish a draft listing, running the domain's activation guards. */
  publishListing(id: string): Promise<V1ListingResponse> {
    return this.#request("post", `/v1/listings/${encodeURIComponent(id)}/publish`, {});
  }

  /** Search active listings across the marketplace. */
  search(query?: V1SearchQuery): Promise<V1SearchResponse> {
    return this.#request("get", "/v1/search", { query });
  }

  /** List the categories active listings are filed under, most populated first. */
  listCategories(query?: V1ListCategoriesQuery): Promise<V1ListCategoriesResponse> {
    return this.#request("get", "/v1/categories", { query });
  }

  /** List orders placed on your listings, newest first. */
  listOrders(query?: V1ListOrdersQuery): Promise<V1ListOrdersResponse> {
    return this.#request("get", "/v1/orders", { query });
  }

  /** Get one order on your listings by id. */
  getOrder(id: string): Promise<V1OrderResponse> {
    return this.#request("get", `/v1/orders/${encodeURIComponent(id)}`, {});
  }

  /**
   * The one place a request is made. `path` is the contract path (`/v1/…`); the `/api` prefix,
   * the key header, and the error contract are applied here so no method restates them.
   */
  async #request<T>(
    method: V1HttpMethod,
    path: string,
    options: { readonly query?: QueryParams | undefined; readonly body?: unknown },
  ): Promise<T> {
    const url = `${this.#baseUrl}${V1_PATH_PREFIX}${path}${buildQueryString(options.query)}`;
    const hasBody = options.body !== undefined;
    const init: RequestInit = {
      method: method.toUpperCase(),
      headers: {
        [OPENAPI_API_KEY_HEADER]: this.#apiKey,
        accept: "application/json",
        ...(hasBody ? { "content-type": "application/json" } : {}),
      },
      ...(hasBody ? { body: JSON.stringify(options.body) } : {}),
    };

    let response: Response;
    let text: string;
    try {
      response = await this.#fetch(url, init);
      // Read inside the same guard: a connection dropped mid-body is the same class of failure as
      // one dropped before the status line, and neither leaves a status worth reasoning about.
      text = await response.text();
    } catch (error) {
      // The transport failed, so there is nothing to report to — rethrow it as the SDK's own
      // type, naming the operation and keeping the original on `cause`.
      throw new MarkaNetworkError(
        `${method.toUpperCase()} ${path} failed: no complete response from the API.`,
        { cause: error },
      );
    }

    if (!response.ok) throw toApiError(response, text);

    const payload = parseJson(text);
    if (payload === undefined) {
      // A 2xx whose body isn't JSON is not a success this client can honour: the declared return
      // type promises a parsed contract object, and handing back `undefined` under that type
      // would surface as an unexplained property access three frames away. Every v1 route answers
      // JSON, so this means a proxy, an error page, or a truncated body wearing a 200.
      throw new MarkaApiError(
        response.status,
        "The API returned a success status with a body that is not JSON.",
        "invalid_response",
      );
    }
    return payload as T;
  }
}

/** The parsed body, or `undefined` when the response was not JSON at all. */
function parseJson(text: string): unknown {
  try {
    return JSON.parse(text) as unknown;
  } catch {
    // error-surfaced: an unparseable body is answered by this function's callers — a success
    // surfaces it as the absent value, a failure falls back to the status line — and there is
    // no fault here to report beyond what they already say.
    return undefined;
  }
}

/**
 * Builds the thrown error for a non-2xx response. A well-formed envelope supplies the message and
 * code; anything else (an HTML gateway page, an empty body) still yields the status, which is the
 * part a caller can act on.
 */
function toApiError(response: Response, text: string): MarkaApiError {
  const payload = parseJson(text);
  if (isErrorEnvelope(payload)) {
    return payload.code === undefined
      ? new MarkaApiError(response.status, payload.error)
      : new MarkaApiError(response.status, payload.error, payload.code);
  }
  const statusText = response.statusText === "" ? "" : ` ${response.statusText}`;
  return new MarkaApiError(
    response.status,
    `Request failed with status ${response.status}${statusText}.`,
  );
}
